// No Dalamud types here (see IChecklistArea.cs). No buttons: these steps are "do this, see that".
namespace Soundstage.Checklist;

/// <summary>Part 11 of the Soundstage plan: the in-game half of the Look tab (ReShade preset per Scene, restore on removal, auto focus).</summary>
public sealed class LookSteps : IChecklistArea
{
    public string Id => "look";
    public string Name => "Part 11: Look (ReShade per Scene, auto focus)";
    public int Order => 110;

    public IReadOnlyList<ChecklistStep> Steps { get; } = new ChecklistStep[]
    {
        new("1", "Copy the add-on in (your step) and restart", "Soundstage never copies files into the game folder, so this is yours. Close the game. In the Soundstage folder run: python tools/build_addon.py. Copy reshade-addon/out/soundstage.addon64 into the FFXIV game folder (the one with dxgi.dll), replacing the Part 3 copy if it is there. Start the game and log in. PASS = ReShade.log has a line with [Soundstage] add-on loaded and, once you are in the world, one saying effect runtime ready, add-on protocol 2."),
        new("2", "Look tab finds the add-on", "Open /soundstage and the Look tab. PASS = the top line is green and says it is switching presets through the Soundstage ReShade add-on, and 'Add-on version 2' shows underneath. FAIL = amber 'Manual' (note the reason sentence under it, and whether step 1 passed)."),
        new("3", "Auto-save warning", "Still on the Look tab. Your ReShade.ini has AutoSavePreset=1, so PASS = an amber paragraph says ReShade saves your preset automatically and that a focus or other setting Soundstage changes can end up saved into your preset file. (If you have turned auto-save off, this step is N/A: mark it Pass and say so.)"),
        new("4", "Map the slots", "Before you start, open ReShade's overlay (Home) and write down which preset is active now: that is your own. On the Look tab the preset folder line shows your reshade-presets folder and a count. Map neon-night, dark-moody and soft-bloom each to a preset that looks clearly different from the others and from yours (use the filter box in the dropdown). PASS = each slot shows its preset path, and pressing Preview on each changes the picture to that look at once."),
        new("5", "Three Scenes switch looks", "In the Lighting tab apply a Scene whose look is neon-night (the neon rim Scenes), then one that is dark-moody, then one that is soft-bloom. PASS = the picture takes the matching preset each time, the Look tab status says 'Look ... applied', and dalamud.log has [Soundstage/LOOK] slot ... -> ... lines. 'Your own preset before a Scene changed it' shows the one you wrote down in step 4, and still shows it after the third Scene (it keeps the first one)."),
        new("6", "Removing the Scene puts your preset back", "Press Remove all in the main window (or Put it back on the Look tab). PASS = your own preset from step 4 is back in ReShade's overlay, the picture returns to how it was before, the Look tab says 'Your own preset is back', and the 'before a Scene changed it' line is gone."),
        new("7", "Unmapped slot is harmless", "On the Look tab set the soft-bloom slot back to (not mapped). Apply the soft-bloom Scene again. PASS = the lights still apply, the look does not change, and the Look tab shows a red line saying the slot is not mapped so nothing changed. Nothing is recorded under 'before a Scene changed it'."),
        new("8", "A Scene with no look leaves your look alone", "Apply a Scene with a mapped look (step 5), then a Scene that has no look slot (a plain Scene with a bare look, if the catalogue has one; otherwise use Remove all). PASS = your own preset is back and the Look tab says so."),
        new("9", "Auto focus follows the camera", "Pick a preset with a depth-of-field shader on (CinematicDOF or similar) and turn it on in ReShade's overlay. On the Look tab press 'Settings from ReShade', open the dropdown next to Focus setting and choose the focus plane or focus depth setting of your shader (the name differs per shader pack). Enter GPose with your character in shot, tick 'Try auto focus now' and move the GPose camera closer and further away. PASS = the sharp plane follows your character's head as you move, the 'Camera to head' line shows the distance and the focus value, and nothing changes while the camera is still. If the focus runs the wrong way or too far, adjust Scale and Offset until it sits on the face (write down the numbers that worked)."),
        new("10", "Auto focus is off by default and per Scene", "Untick 'Try auto focus now'. PASS = the focus stops following. Apply a Scene: its 'Auto focus for the applied Scene' box is unticked. Tick it and PASS = focus follows again; apply another Scene and PASS = it is off again (it is stored in the Scene, so the saved Scene carries it, and no shipped Scene has it on)."),
        new("11", "Focus setting goes back", "With auto focus having moved the focus setting, remove the Scene (Remove all). PASS = the focus setting in ReShade's overlay reads the value it had before auto focus started (check the number against what you saw earlier), and ReShade.log has an OK restored line. Because auto-save is on, also note whether your preset file now has the old value: it should."),
        new("12", "Reload leaves the pipe free", "With a Scene look applied, reload the plugin (/xlplugins or Dev Plugins: disable then enable Soundstage). PASS = the game does not freeze, your own preset is back after the disable, and after the enable the Look tab goes green again (the add-on's pipe was not left held). ReShade.log has an unload line from Soundstage."),
        new("13", "No add-on: the manual route", "Close the game, rename soundstage.addon64 in the game folder to soundstage.addon64.off, start the game and open the Look tab. PASS = the top line is amber 'Manual', the reason says the add-on did not answer, applying a Scene shows 'Pick <preset> in ReShade's own preset list', and Copy name copies the preset path. Then close the game and put the file name back. (Binding a shortcut key to one preset in ReShade's own settings and pressing it by hand is the manual option: Soundstage never sends keys and never edits ReShade.ini.)"),
    };
}
